import CoreBluetooth
import AVFoundation

final class PINBLEManager: NSObject, CBCentralManagerDelegate, CBPeripheralDelegate {
    private var audioBuffer = Data()
    private let audioServiceUUID = CBUUID(string: "0000FFE0-0000-1000-8000-00805F9B34FB")
    private let audioCharUUID  = CBUUID(string: "0000FFE1-0000-1000-8000-00805F9B34FB")

    func peripheral(_ peripheral: CBPeripheral,
                    didUpdateValueFor characteristic: CBCharacteristic,
                    error: Error?) {
        guard error == nil, let data = characteristic.value else { return }
        audioBuffer.append(data)
        // Silence detector placeholder — flush to Whisper when buffer exceeds threshold
        if audioBuffer.count >= 32_000 * 2 { // ~1 s of 16-kHz 16-bit mono
            Task { await transcribe(pcm: audioBuffer) }
            audioBuffer.removeAll(keepingCapacity: true)
        }
    }

    private func transcribe(pcm: Data) async {
        // POST raw PCM wrapped in a WAV envelope to the FastAPI relay /transcribe endpoint
        guard let url = URL(string: "https://relay.example.com/transcribe") else { return }
        var request = URLRequest(url: url)
        request.httpMethod = "POST"
        request.setValue("audio/wav", forHTTPHeaderField: "Content-Type")
        request.httpBody = wrapPCMAsWAV(pcm, sampleRate: 16_000)
        let (data, _) = try! await URLSession.shared.data(for: request)
        let result = try! JSONDecoder().decode(TranscriptionResult.self, from: data)
        await sendToGPT(text: result.text)
    }
}
